import heapq
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0]) if grid else 0

    def free(cell: Tuple[int, int]) -> bool:
        r, c = cell
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # validate start and goal
    if not (free(start) and free(goal)):
        return []
    if start == goal:
        return [start]

    # Dijkstra (all edges weight 1) to find a path
    dist = {start: 0}
    parent = {}
    heap = [(0, start)]

    while heap:
        d, cur = heapq.heappop(heap)
        if cur == goal:
            break
        if d != dist[cur]:
            continue  # outdated entry

        r, c = cur
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            nxt = (nr, nc)
