                dist[nxt] = nd
                parent[nxt] = cur
                heapq.heappush(heap, (nd, nxt))

    if goal not in dist:
        return []  # unreachable

    # reconstruct path
    path = []
    cur = goal
    while cur != start:
        path.append(cur)
        cur = parent[cur]
    path.append(start)
    path.reverse()
