def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    sr, sc = start
    gr, gc = goal

    # Validate start and goal cells
    if not (0 <= sr < rows and 0 <= sc < cols and
            0 <= gr < rows and 0 <= gc < cols):
        return []
    if grid[sr][sc] == '#' or grid[gr][gc] == '#':
        return []

    # Trivial case
    if start == goal:
        return [start]

    # Distance matrix: None = unreachable so far
    dist = [[None] * cols for _ in range(rows)]
    dist[sr][sc] = 0

    # Propagation loop (wave‑front flood fill)
    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if dist[r][c] is None or grid[r][c] == '#':
                    continue
                d = dist[r][c] + 1
                for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and dist[nr][nc] is None:
                        dist[nr][nc] = d
                        changed = True

    # No path found
    if dist[gr][gc] is None:
        return []

    # Reconstruct a path from goal back to start
    path_rev = [(gr, gc)]
    cur_r, cur_c = gr, gc
    cur_d = dist[gr][gc]
    while (cur_r, cur_c) != (sr, sc):
        for nr, nc in ((cur_r-1, cur_c), (cur_r+1, cur_c), (cur_r, cur_c-1), (cur_r, cur_c+1)):
            if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] == cur_d - 1:
                path_rev.append((nr, nc))
                cur_r, cur_c = nr, nc
                cur_d -= 1
                break

    return list(reversed(path_rev))
