import random
from typing import List, Tuple

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0]) if grid else 0

    # helper to check cell validity
    def free(cell):
        r, c = cell
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # start/goal validation
    if not (free(start) and free(goal)):
        return []
    if start == goal:
        return [start]

    # map cell to id and vice‑versa
    cell_id = {}
    id_cell = {}
    nid = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':
                cell_id[(r, c)] = nid
                id_cell[nid] = (r, c)
                nid += 1

    n = nid
    start_id = cell_id[start]
    goal_id  = cell_id[goal]

    # Union‑Find structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            xr, yr = yr, xr
        parent[yr] = xr
        if rank[xr] == rank[yr]:
            rank[xr] += 1
        return True

    # tree_parent holds a directed edge for the spanning forest
    tree_parent = [-1] * n

    # collect all possible edges between free neighbours
    edges = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '.':
                continue
            cur = cell_id[(r, c)]
            for dr, dc in ((0, 1), (1, 0)):  # right and down to avoid duplicates
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    nxt = cell_id[(nr, nc)]
                    edges.append((cur, nxt))

    random.shuffle(edges)          # any order is fine

    # Kruskal‑like construction until start and goal become connected
    for u, v in edges:
        if union(u, v):
            # orient edge arbitrarily: make v child of u
            tree_parent[v] = u
            if find(start_id) == find(goal_id):
                break

    if find(start_id) != find(goal_id):
        return []   # no path

