    total = rows * cols
    parent = list(range(total))
    rank = [0] * total
    tree_parent = {}          # child -> parent in the spanning forest

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        # union by rank, attach ry under rx
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        tree_parent[ry] = rx   # record tree edge

    # build edges between orthogonal free neighbours (right & down to avoid duplicates)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '.':
                continue
            cur = to_id(r, c)
            if c + 1 < cols and grid[r][c + 1] == '.':
                union(cur, to_id(r, c + 1))
            if r + 1 < rows and grid[r + 1][c] == '.':
