                u, v = (r, c), (nr, nc)
                ru, rv = find(u), find(v)
                if ru != rv:
                    # attach the root of u's component to v (adjacent)
                    union(ru, rv, v)

    # check connectivity
    if find(start) != find(goal):
        return []

    # build ancestor chains using tree_parent edges
    def ancestors(cell):
        chain = []
        while cell is not None:
            chain.append(cell)
            cell = tree_parent[cell]
        return chain

    anc_start = ancestors(start)
    anc_goal = ancestors(goal)

    set_start = set(anc_start)
    lca = None
    for node in anc_goal:
        if node in set_start:
            lca = node
            break

    if lca is None:
        return []  # should not happen if connected

    # compose path: start → lca, then lca ← goal
    path_to_lca = anc_start[:anc_start.index(lca) + 1]
    path_from_goal = anc_goal[:anc_goal.index(lca)]
    path = path_to_lca + list(reversed(path_from_goal))
    return path
