def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    # helper to check if a cell is free
    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # quick checks for start/goal validity
    if not (is_free(*start) and is_free(*goal)):
        return [] if start != goal else ([] if not is_free(*start) else [start])

    # map each free cell to a compact index
    idx_of = {}
    cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':
                idx = len(cells)
                idx_of[(r, c)] = idx
                cells.append((r, c))

    n = len(cells)
    INF = 10 ** 9

    # distance and next matrices
    dist = [[INF] * n for _ in range(n)]
    nxt = [[None] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0
        nxt[i][i] = i

    # add edges (orthogonal moves)
    for r, c in cells:
        i = idx_of[(r, c)]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                j = idx_of[(nr, nc)]
                dist[i][j] = 1
                nxt[i][j] = j

    # Floyd‑Warshall with path reconstruction
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            nik = nxt[i][k]
            for j in range(n):
                alt = dik + dk[j]
                if alt < di[j]:
                    di[j] = alt
                    nxt[i][j] = nik

    s_idx = idx_of[start]
    g_idx = idx_of[goal]

    if dist[s_idx][g_idx] == INF:
        return []

    # reconstruct path using nxt matrix
    path_idx = [s_idx]
    while path_idx[-1] != g_idx:
        cur = path_idx[-1]
        nxt_step = nxt[cur][g_idx]
        if nxt_step is None:
            return []  # should not happen
        path_idx.append(nxt_step)

    # convert indices back to coordinates
    return [cells[i] for i in path_idx]
